const raw = $input.item.json || {};
function findDeep(obj, key, depth = 0) {
  if (depth > 5 || !obj || typeof obj !== 'object') return null;
  if (obj[key] !== undefined && obj[key] !== null) return obj[key];
  for (const k of Object.keys(obj)) {
    const f = findDeep(obj[k], key, depth + 1);
    if (f !== null && f !== undefined) return f;
  }
  return null;
}
const project_id = findDeep(raw, 'project_id');
if (!project_id) throw new Error('WF-02 Error: project_id missing.');
const ep = Number(findDeep(raw, 'episode_number') || findDeep(raw, 'episode_no') || 1);
const user_prompt = (findDeep(raw, 'user_prompt') || findDeep(raw, 'userPrompt') || findDeep(raw, 'prompt') || findDeep(raw, 'rawText') || `Generate story for Ep ${ep}`).toString().trim();
return { json: { ...raw, project_id, episode_number: ep, episode_no: ep, mode: 'SAVE', user_prompt, sessionId: findDeep(raw, 'sessionId') || `sess_${$execution.id}`, user_infrastructure: findDeep(raw, 'user_infrastructure') || {}, project_style: findDeep(raw, 'project_style') || {} } };

const base = $('Normalize Input & Lock SAVE Mode').item.json;

function extractRows(nodeName, requiredKey) {
  try {
    const rawItems = $(nodeName).all().map(i => i.json);
    const out = [];
    for (const item of rawItems) {
      if (Array.isArray(item)) {
        for (const row of item) {
          if (row && (requiredKey ? row[requiredKey] !== undefined : Object.keys(row).length > 0)) out.push(row);
        }
      } else if (item && (requiredKey ? item[requiredKey] !== undefined : Object.keys(item).length > 0)) {
        out.push(item);
      }
    }
    return out;
  } catch (e) { return []; }
}

const projectRows = extractRows('Supabase: Fetch Project & Bible', 'id');
const projectRec = projectRows[0] || {};
const storyBible = projectRec.story_bible || {};
const resolvedSeason = Number(projectRec.current_season || base.season_no || 1);

const canonFacts = extractRows('Supabase: Fetch Canon Facts', 'fact_key');
const snapshots = extractRows('Supabase: Fetch Latest Story Snapshot', 'snapshot_data');
const latestSnapshot = snapshots[0] ? snapshots[0].snapshot_data : null;
const characters = extractRows('Supabase: Fetch Characters & Voice Config', 'character_code');
const mysteries = extractRows('Supabase: Fetch Mystery Tracker', 'description');
const timelineEvents = extractRows('Supabase: Fetch Story Timeline', 'event_description');
const sceneLibrary = extractRows('Supabase: Fetch Scene Library', 'reuse_key');
const motionLibrary = extractRows('Supabase: Fetch Motion Library', 'motion_key');

const characterVoiceMap = {};
for (const ch of characters) {
  const code = (ch.character_code || '').toString().toUpperCase().trim();
  if (!code) continue;
  const vc = (ch.voice_config && typeof ch.voice_config === 'object') ? ch.voice_config : {};
  characterVoiceMap[code] = {
    character_code: code, name: ch.name || code, visual_dna: ch.visual_dna || {},
    voice_id: vc.voice_id || 'svara_hi_male_hero_01', voice_provider: vc.voice_provider || 'Svara TTS',
    voice_model: vc.voice_model || 'svara-v2-hi', language: vc.language || 'hi', gender: vc.gender || 'male',
    pitch: Number(vc.pitch ?? 1.0), speed: Number(vc.speed ?? 1.0),
    emotion_profile: vc.emotion_profile || { neutral: { pitch: 1.00, rate: 1.00 }, anger: { pitch: 0.95, rate: 1.10 }, joy: { pitch: 1.05, rate: 1.05 }, sadness: { pitch: 0.90, rate: 0.90 }, fear: { pitch: 1.02, rate: 1.08 } }
  };
}

characterVoiceMap['NARRATOR'] = {
  character_code: 'NARRATOR', name: 'Narrator', visual_dna: {},
  voice_id: 'svara_hi_narrator_epic_01', voice_provider: 'Svara TTS', voice_model: 'svara-v2-hi',
  language: 'hi', gender: 'male', pitch: 0.98, speed: 1.0,
  emotion_profile: { neutral: { pitch: 1.00, rate: 1.00 }, anger: { pitch: 0.95, rate: 1.10 }, joy: { pitch: 1.05, rate: 1.05 }, sadness: { pitch: 0.90, rate: 0.90 }, fear: { pitch: 1.02, rate: 1.08 } }
};

const continuityPromptContext = [
  `=== PROJECT & SEASON CONTEXT ===`,
  `Project: ${projectRec.name || base.project_name} | Season: ${resolvedSeason} | Target Episode: ${base.episode_no}`,
  `=== 1. MASTER STORY BIBLE & SEASON ARC ===`,
  JSON.stringify(storyBible),
  `=== 2. APPROVED CANON FACTS ===`,
  canonFacts.length > 0 ? canonFacts.map(f => `[${f.canon_status}] (${f.fact_type}) ${f.fact_key}: ${JSON.stringify(f.fact_value)}`).join('\n') : 'No explicit canon_facts rows yet.',
  `=== 3. LATEST COMMITTED STORY STATE SNAPSHOT ===`,
  latestSnapshot ? JSON.stringify(latestSnapshot) : 'Episode 1 / Initial State — No prior episode snapshot.',
  `=== 4. REGISTERED CHARACTERS & VOICE CONFIGS (Rule 39) ===`,
  characters.length > 0 ? characters.map(c => `- ${c.character_code} (${c.name}): voice_id=${c.voice_config?.voice_id || 'default'} | visual_dna=${JSON.stringify(c.visual_dna || {})}`).join('\n') : '- CHAR_001 (Protagonist) | NARRATOR',
  `=== 5. OPEN & PARTIAL MYSTERIES ===`,
  mysteries.length > 0 ? mysteries.map(m => `- [${m.status}] ${m.mystery_id || ''}: ${m.description} (Clues: ${JSON.stringify(m.clues || [])})`).join('\n') : 'None',
  `=== 6. RECENT STORY TIMELINE ===`,
  timelineEvents.length > 0 ? timelineEvents.map(t => `- Ep ${t.episode_no} (${t.event_code || ''}): ${t.event_description} @ ${t.location || 'UNKNOWN'} — Participants: ${JSON.stringify(t.characters_involved || [])}`).join('\n') : 'None',
  `=== 7. REUSABLE SCENE & MOTION LIBRARY KEYS ===`,
  `Scene Keys: ${sceneLibrary.map(s => s.reuse_key).join(', ') || 'None'}`,
  `Motion Keys: ${motionLibrary.map(m => m.motion_key).join(', ') || 'None'}`
].join('\n\n');

return { json: { ...base, season_no: resolvedSeason, season_number: resolvedSeason, character_voice_map: characterVoiceMap, scene_library_keys: sceneLibrary.map(s => s.reuse_key), motion_library_keys: motionLibrary.map(m => m.motion_key), continuity_prompt_context: continuityPromptContext } };

const ctx = $('Context Assembly & Prompt Constructor').item.json;
const llmRaw = $input.item.json;

let stage1 = null;
try {
  const rawContent = llmRaw?.choices?.[0]?.message?.content;
  if (rawContent) {
    const clean = rawContent.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    stage1 = JSON.parse(clean);
  }
} catch (e) { stage1 = null; }

const registeredCharCodes = Object.keys(ctx.character_voice_map).filter(k => k !== 'NARRATOR');
const primaryChar = registeredCharCodes[0] || 'CHAR_001';

if (!stage1 || !Array.isArray(stage1.beats) || stage1.beats.length === 0) {
  stage1 = {
    title: `Episode ${ctx.episode_no}: Shadows of Canon`, logline: `Protagonist ${primaryChar} uncovers a critical truth.`,
    objective: `Advance main season arc.`, opening_hook: `A tense confrontation.`, climax: `Unleashing a forbidden technique.`, cliffhanger: `An artifact resonates with an unknown signal.`,
    full_script_text: `[EPISODE ${ctx.episode_no} SCRIPT]\nScene 1: Opening.\nScene 2: Climax.`,
    beats: [
      { beat_order: 1, location_code: 'LOC_001', visual_description: 'Wide cinematic anime shot of courtyard.', action_description: 'Camera pans slowly.', dialogue_speaker_id: 'NARRATOR', dialogue_text: 'Us raat, aasmaan bhi khoon ke aansu ro raha tha.', mouth_visible: false, emotion: 'sadness', is_climax_beat: false },
      { beat_order: 2, location_code: 'LOC_001', visual_description: `Close-up of ${primaryChar}.`, action_description: `${primaryChar} speaks directly.`, dialogue_speaker_id: primaryChar, dialogue_text: 'Main peeche nahi hatunga!', mouth_visible: true, emotion: 'anger', is_climax_beat: false },
      { beat_order: 3, location_code: 'LOC_001', visual_description: 'Dynamic action shot.', action_description: 'High-speed sword slash.', dialogue_speaker_id: primaryChar, dialogue_text: 'Ab faisla hoga!', mouth_visible: true, emotion: 'anger', is_climax_beat: true }
    ]
  };
}

return { json: { ...ctx, stage1_script: stage1 } };

const ctx = $('Stage 1 Parser & Stage 2 Prompt Builder').item.json;
const stage1 = ctx.stage1_script;
const voiceMap = ctx.character_voice_map || {};
const llmRaw = $input.item.json;

const ALLOWED_EMOTIONS = new Set(['neutral', 'anger', 'joy', 'sadness', 'fear']);
const ALLOWED_CAMERA = new Set(['NONE', 'PAN', 'ZOOM', 'KEN_BURNS']);

function toStrictBool(val, defaultVal = false) {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') {
    const lower = val.trim().toLowerCase();
    if (lower === 'true' || lower === '1' || lower === 'yes') return true;
    if (lower === 'false' || lower === '0' || lower === 'no') return false;
  }
  if (typeof val === 'number') return val !== 0;
  return Boolean(defaultVal);
}

let rawScenes = null;
try {
  const content = llmRaw?.choices?.[0]?.message?.content;
  if (content) {
    const clean = content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    const parsed = JSON.parse(clean);
    if (parsed && Array.isArray(parsed.scenes) && parsed.scenes.length > 0) rawScenes = parsed.scenes;
  }
} catch (e) { rawScenes = null; }

if (!rawScenes) {
  rawScenes = (stage1.beats || []).map((b, idx) => ({
    scene_order: idx + 1, beat_order: b.beat_order || (idx + 1), location_code: b.location_code || 'LOC_001',
    visual_prompt: b.visual_description || 'Cinematic anime frame', action_summary: b.action_description || 'Camera movement',
    dialogue_speaker_id: b.dialogue_speaker_id || null, voice_text: b.dialogue_text || null, emotion: b.emotion || 'neutral',
    duration_sec: 5, needs_image: true, needs_voice: Boolean(b.dialogue_text), mouth_visible: toStrictBool(b.mouth_visible, false),
    needs_lipsync: Boolean(b.dialogue_text) && toStrictBool(b.mouth_visible, false), needs_motion: toStrictBool(b.is_climax_beat, false),
    needs_expression: false, needs_camera_motion: !toStrictBool(b.is_climax_beat, false), needs_subtitles: Boolean(b.dialogue_text),
    needs_bgm: true, needs_sfx: true, camera_motion_type: toStrictBool(b.is_climax_beat, false) ? 'NONE' : 'KEN_BURNS',
    bgm_hint: { category: b.is_climax_beat ? 'battle_orchestral' : 'ambient_tension', mood: b.emotion || 'neutral' },
    sfx_hint: b.is_climax_beat ? ['sword_clash', 'wind_whoosh'] : ['rain_ambience']
  }));
}

const validationWarnings = [];
const sanitizedScenes = [];
const scenesDbBatch = [];
const clipsDbBatch = [];

for (let i = 0; i < rawScenes.length; i++) {
  const s = rawScenes[i] || {};
  const sceneOrder = Number(s.scene_order || (i + 1));

  const rawEmotion = (s.emotion || 'neutral').toString().toLowerCase().trim();
  let emotion = rawEmotion;
  if (!ALLOWED_EMOTIONS.has(emotion)) {
    validationWarnings.push(`Scene ${sceneOrder}: Unknown emotion "${s.emotion}" overridden to "neutral".`);
    emotion = 'neutral';
  }

  const voiceText = s.voice_text ? s.voice_text.toString().trim() : null;
  const hasDialogue = Boolean(voiceText && voiceText.length > 0);
  const rawSpeaker = s.dialogue_speaker_id ? s.dialogue_speaker_id.toString().toUpperCase().trim() : (hasDialogue ? 'NARRATOR' : null);
  const speakerProfile = (rawSpeaker && voiceMap[rawSpeaker]) ? voiceMap[rawSpeaker] : (hasDialogue ? voiceMap['NARRATOR'] : null);

  const resolvedVoiceId = speakerProfile ? speakerProfile.voice_id : null;
  const emotionMod = speakerProfile?.emotion_profile?.[emotion] || { pitch: 1.00, rate: 1.00 };
  const voiceModifiers = speakerProfile ? {
    voice_id: resolvedVoiceId, voice_provider: speakerProfile.voice_provider, voice_model: speakerProfile.voice_model,
    language: speakerProfile.language, emotion, pitch: Number((speakerProfile.pitch * (emotionMod.pitch || 1.0)).toFixed(2)),
    rate: Number((speakerProfile.speed * (emotionMod.rate || 1.0)).toFixed(2))
  } : null;

  const needs_image = toStrictBool(s.needs_image, true);
  const needs_voice = hasDialogue ? toStrictBool(s.needs_voice, true) : false;
  const mouth_visible = hasDialogue && rawSpeaker !== 'NARRATOR' ? toStrictBool(s.mouth_visible, false) : false;
  let needs_lipsync = needs_voice && mouth_visible ? toStrictBool(s.needs_lipsync, true) : false;
  let needs_motion = toStrictBool(s.needs_motion, false);
  let needs_expression = toStrictBool(s.needs_expression, false);
  let needs_camera_motion = toStrictBool(s.needs_camera_motion, true);
  const needs_subtitles = needs_voice ? toStrictBool(s.needs_subtitles, true) : false;
  const needs_bgm = toStrictBool(s.needs_bgm, true);
  const needs_sfx = toStrictBool(s.needs_sfx, false);

  let camera_motion_type = (s.camera_motion_type || 'KEN_BURNS').toString().toUpperCase().trim();
  if (!ALLOWED_CAMERA.has(camera_motion_type)) camera_motion_type = needs_camera_motion ? 'KEN_BURNS' : 'NONE';

  const actionText = `${s.action_summary || ''} ${s.visual_prompt || ''}`.toLowerCase();
  const hasEssentialPhysicalAction = /\b(fight|slash|attack|run|leap|jump|dodge|explosion|transform|chase|strike|punch|kick|sprint|clash)\b/i.test(actionText);

  if (['PAN', 'ZOOM', 'KEN_BURNS'].includes(camera_motion_type) && needs_motion && !hasEssentialPhysicalAction) {
    needs_motion = false;
    needs_camera_motion = true;
    validationWarnings.push(`Scene ${sceneOrder}: Rule 37 enforced — camera motion (${camera_motion_type}) demoted to CPU.`);
  }

  if (!mouth_visible && needs_lipsync) {
    needs_lipsync = false;
    validationWarnings.push(`Scene ${sceneOrder}: mouth_visible=false enforced needs_lipsync=false.`);
  }

  if (camera_motion_type === 'NONE') needs_camera_motion = false; else needs_camera_motion = true;

  const activeGpuCount = [needs_lipsync, needs_motion, needs_expression].filter(Boolean).length;
  let routing_type = 'STATIC'; let gpu_priority = 'P0'; let defaultReason = 'Rule 37: Static frame on CPU.';

  if (activeGpuCount > 1) {
    routing_type = 'COMBINED'; gpu_priority = 'P5'; defaultReason = `Rule 38 P5 Combined GPU.`;
  } else if (needs_motion) {
    routing_type = 'MOTION'; gpu_priority = 'P4'; defaultReason = 'Rule 38 P4 AnimateDiff GPU.';
  } else if (needs_expression) {
    routing_type = 'EXPRESSION'; gpu_priority = 'P3'; defaultReason = 'Rule 38 P3 LivePortrait GPU.';
  } else if (needs_lipsync && mouth_visible) {
    routing_type = 'LIPSYNC'; gpu_priority = 'P2'; defaultReason = `Rule 38 P2 MuseTalk GPU: (${rawSpeaker}).`;
  } else if (needs_camera_motion && camera_motion_type !== 'NONE') {
    routing_type = camera_motion_type; gpu_priority = 'P1'; defaultReason = `Rule 37 & 38 P1 FFmpeg CPU: (${camera_motion_type}).`;
  } else {
    routing_type = 'STATIC'; gpu_priority = 'P0'; defaultReason = 'Rule 37 & 38 P0 FFmpeg CPU: Static.';
  }

  const routing_reason = (s.routing_reason && s.routing_reason.toString().trim().length > 5) ? `${s.routing_reason.toString().trim()} [${gpu_priority}/${routing_type}]` : defaultReason;
  const bgm_hint = (s.bgm_hint && typeof s.bgm_hint === 'object') ? { category: (s.bgm_hint.category || 'cinematic_anime').toString(), mood: (s.bgm_hint.mood || emotion).toString() } : { category: 'cinematic_anime', mood: emotion };
  const sfx_hints = Array.isArray(s.sfx_hint) ? s.sfx_hint.map(x => x.toString()) : (Array.isArray(s.sfx_hints) ? s.sfx_hints.map(x => x.toString()) : (s.sfx_hint ? [s.sfx_hint.toString()] : []));

  const cleanScene = {
    project_id: ctx.project_id, episode_no: ctx.episode_no, scene_order: sceneOrder, beat_order: Number(s.beat_order || sceneOrder),
    location_code: (s.location_code || 'LOC_001').toString(), visual_prompt: (s.visual_prompt || 'Anime cinematic frame').toString(),
    action_summary: (s.action_summary || '').toString(), dialogue_speaker_id: rawSpeaker, voice_id: resolvedVoiceId, voice_text: voiceText,
    emotion, voice_modifiers: voiceModifiers, duration_sec: Number(s.duration_sec || 5),
    needs_image, needs_voice, needs_lipsync, needs_motion, needs_expression, needs_camera_motion, needs_subtitles, needs_bgm, needs_sfx, mouth_visible,
    camera_motion_type, routing_type, gpu_priority, routing_reason, bgm_hint, sfx_hint: sfx_hints
  };

  sanitizedScenes.push(cleanScene);

  // STRICT SCHEMA FIX: Only push columns that EXIST in scenes table
  scenesDbBatch.push({
    project_id: ctx.project_id,
    episode_no: ctx.episode_no, // Requires ALTER TABLE scenes ADD COLUMN episode_no
    scene_order: sceneOrder,
    description: cleanScene.visual_prompt, // visual_prompt -> description
    dialogue_speaker_id: cleanScene.dialogue_speaker_id,
    needs_image: cleanScene.needs_image,
    needs_voice: cleanScene.needs_voice,
    needs_lipsync: cleanScene.needs_lipsync,
    needs_motion: cleanScene.needs_motion,
    needs_expression: cleanScene.needs_expression,
    needs_camera_motion: cleanScene.needs_camera_motion,
    needs_subtitles: cleanScene.needs_subtitles,
    needs_bgm: cleanScene.needs_bgm,
    needs_sfx: cleanScene.needs_sfx,
    mouth_visible: cleanScene.mouth_visible,
    camera_motion_type: cleanScene.camera_motion_type,
    routing: cleanScene.routing_type, // routing_type -> routing
    gpu_priority: cleanScene.gpu_priority,
    gpu_required: ['P2','P3','P4','P5'].includes(cleanScene.gpu_priority),
    routing_reason: cleanScene.routing_reason
  });

  // STRICT SCHEMA FIX: Only push columns that EXIST in clips table
  clipsDbBatch.push({
    project_id: ctx.project_id,
    episode_no: ctx.episode_no,
    scene_order: sceneOrder,
    voice_text: cleanScene.voice_text,
    voice_id: cleanScene.voice_id,
    emotion: cleanScene.emotion,
    bgm_hint: cleanScene.bgm_hint,
    sfx_hints: cleanScene.sfx_hint,
    voice_modifiers: cleanScene.voice_modifiers,
    character_code: cleanScene.dialogue_speaker_id,
    needs_image: cleanScene.needs_image,
    needs_voice: cleanScene.needs_voice,
    needs_lipsync: cleanScene.needs_lipsync,
    needs_motion: cleanScene.needs_motion,
    needs_expression: cleanScene.needs_expression,
    needs_camera_motion: cleanScene.needs_camera_motion,
    needs_subtitles: cleanScene.needs_subtitles,
    needs_bgm: cleanScene.needs_bgm,
    needs_sfx: cleanScene.needs_sfx,
    mouth_visible: cleanScene.mouth_visible,
    camera_motion_type: cleanScene.camera_motion_type,
    routing: cleanScene.routing_type,
    routing_hint: cleanScene.routing_type,
    gpu_priority: cleanScene.gpu_priority,
    gpu_required: ['P2','P3','P4','P5'].includes(cleanScene.gpu_priority),
    routing_reason: cleanScene.routing_reason,
    status: 'PENDING'
  });
}

const scriptJsonPayload = {
  episode_no: ctx.episode_no, season_no: ctx.season_no, title: stage1.title || `Episode ${ctx.episode_no}`,
  logline: stage1.logline || '', objective: stage1.objective || '', opening_hook: stage1.opening_hook || '',
  climax: stage1.climax || '', cliffhanger: stage1.cliffhanger || '', total_scenes: sanitizedScenes.length,
  validation_warnings: validationWarnings, scenes: sanitizedScenes
};

const episodeDbRecord = {
  project_id: ctx.project_id, episode_no: ctx.episode_no, title: scriptJsonPayload.title,
  script: stage1.full_script_text || sanitizedScenes.map(sc => `[Scene ${sc.scene_order}] (${sc.location_code}) ${sc.visual_prompt} | ${sc.dialogue_speaker_id || 'SILENT'}: ${sc.voice_text || ''}`).join('\n'),
  current_state: 'SCENE_PLAN_READY', script_json: scriptJsonPayload
};

const episodeStateDbRecord = { project_id: ctx.project_id, episode_no: ctx.episode_no, current_state: 'SCENE_PLAN_READY' };

return { json: { ...ctx, episode_db_record: episodeDbRecord, scenes_db_batch: scenesDbBatch, clips_db_batch: clipsDbBatch, episode_state_db_record: episodeStateDbRecord, script_json: scriptJsonPayload, validation_warnings: validationWarnings } };

const state = $('Output Validator, Rule 37 & JSON Sanitizer').item.json;
const sj = state.script_json;
const scenes = sj.scenes || [];
const priorityCounts = { P0: 0, P1: 0, P2: 0, P3: 0, P4: 0, P5: 0 };
const emotionCounts = { neutral: 0, anger: 0, joy: 0, sadness: 0, fear: 0 };
for (const sc of scenes) {
  if (priorityCounts[sc.gpu_priority] !== undefined) priorityCounts[sc.gpu_priority]++;
  if (emotionCounts[sc.emotion] !== undefined) emotionCounts[sc.emotion]++;
}
const cpuSceneCount = priorityCounts.P0 + priorityCounts.P1;
const gpuSceneCount = priorityCounts.P2 + priorityCounts.P3 + priorityCounts.P4 + priorityCounts.P5;
const summaryMessage = [
  `🎬 **WF-02: Episode ${state.episode_no} Story & Scene Plan Ready!**`,
  `📌 **Title:** ${sj.title}`,
  `📝 **Logline:** ${sj.logline}`,
  `🔒 **Mode:** ${state.mode} | **State:** \`SCENE_PLAN_READY\``,
  `📊 **Routing Breakdown (${scenes.length} Scenes):** CPU: ${cpuSceneCount} | GPU: ${gpuSceneCount}`,
  state.validation_warnings.length > 0 ? `\n⚠️ **Governance Auto-Corrections (${state.validation_warnings.length}):**\n` + state.validation_warnings.slice(0, 5).map(w => `• ${w}`).join('\n') : ''
].filter(Boolean).join('\n');
return { json: { ok: true, status: 'SCENE_PLAN_READY', workflow_name: 'WF-02', execution_id: $execution.id, project_id: state.project_id, project_name: state.project_name, episode_no: state.episode_no, season_no: state.season_no, mode: state.mode, current_state: 'SCENE_PLAN_READY', next_workflow_id: $env.WF_03_PROD_ID || null, wf03_dispatch_payload: { user_infrastructure: $('When Executed by Another Workflow').first().json.user_infrastructure, project_style: $('When Executed by Another Workflow').first().json.project_style, project_id: state.project_id, episode_no: state.episode_no, season_no: state.season_no, mode: 'SAVE', current_state: 'SCENE_PLAN_READY', total_scenes: scenes.length, cpu_scenes: cpuSceneCount, gpu_scenes: gpuSceneCount, priority_breakdown: priorityCounts, scenes: scenes }, output: summaryMessage, text: summaryMessage } };

